body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Oxygen',
        'Ubuntu', 'Cantarell', 'Fira Sans', 'Droid Sans', 'Helvetica Neue',
        sans-serif;
    background: linear-gradient(135deg, #f5f7fa 0%, #c3cfe2 100%);
    min-height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 20px;
}

.container {
    width: 100%;
    max-width: 600px;
}

.form-wrapper {
    background: white;
    border-radius: 12px;
    box-shadow: 0 10px 40px rgba(0, 0, 0, 0.1);
    padding: 48px 40px;
}

h1 {
    font-size: 28px;
    font-weight: 600;
    color: #1a202c;
    margin-bottom: 12px;
    letter-spacing: -0.5px;
}

.intro-text {
    font-size: 16px;
    color: #718096;
    margin-bottom: 32px;
    line-height: 1.5;
}

.consent-form {
    margin: 32px 0;
}

.form-field {
    margin-bottom: 24px;
}

.checkbox-label {
    display: flex;
    align-items: flex-start;
    gap: 12px;
    cursor: pointer;
    user-select: none;
}

.checkbox-label input[type="checkbox"] {
    position: absolute;
    opacity: 0;
    width: 0;
    height: 0;
}

.checkbox-custom {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 20px;
    height: 20px;
    min-width: 20px;
    border: 2px solid #cbd5e0;
    border-radius: 4px;
    background: white;
    transition: all 0.2s ease;
    margin-top: 2px;
}

.checkbox-label input[type="checkbox"]:checked + .checkbox-custom {
    background: #4299e1;
    border-color: #4299e1;
}

.checkbox-label input[type="checkbox"]:checked + .checkbox-custom::after {
    content: '✓';
    color: white;
    font-size: 14px;
    font-weight: bold;
}

.checkbox-label input[type="checkbox"]:focus + .checkbox-custom {
    outline: 2px solid #4299e1;
    outline-offset: 2px;
}

.checkbox-label input[type="checkbox"]:disabled + .checkbox-custom {
    background: #edf2f7;
    border-color: #cbd5e0;
    cursor: not-allowed;
}

.label-text {
    font-size: 16px;
    color: #2d3748;
    line-height: 1.5;
}

.label-text a {
    color: #4299e1;
    text-decoration: none;
    border-bottom: 1px solid transparent;
    transition: border-color 0.2s ease;
}

.label-text a:hover {
    border-bottom-color: #4299e1;
}

.label-text a:focus {
    outline: 2px solid #4299e1;
    outline-offset: 2px;
    border-radius: 2px;
}

.helper-text {
    font-size: 13px;
    color: #a0aec0;
    margin-top: 8px;
    margin-left: 32px;
    line-height: 1.4;
}

.submit-button {
    width: 100%;
    padding: 12px 24px;
    font-size: 16px;
    font-weight: 600;
    color: white;
    background: #4299e1;
    border: none;
    border-radius: 6px;
    cursor: pointer;
    transition: all 0.2s ease;
    margin-top: 24px;
}

.submit-button:hover:not(:disabled) {
    background: #3182ce;
    box-shadow: 0 4px 12px rgba(66, 153, 225, 0.3);
    transform: translateY(-1px);
}

.submit-button:active:not(:disabled) {
    transform: translateY(0);
    box-shadow: 0 2px 6px rgba(66, 153, 225, 0.2);
}

.submit-button:focus {
    outline: 2px solid #4299e1;
    outline-offset: 2px;
}

.submit-button:disabled {
    background: #cbd5e0;
    cursor: not-allowed;
    opacity: 0.6;
}

.footer-text {
    font-size: 13px;
    color: #a0aec0;
    text-align: center;
    margin-top: 24px;
    line-height: 1.4;
}

/* Responsive design */
@media (max-width: 480px) {
    .form-wrapper {
        padding: 32px 24px;
    }

    h1 {
        font-size: 24px;
    }

    .intro-text {
        font-size: 14px;
        margin-bottom: 24px;
    }

    .checkbox-custom {
        width: 18px;
        height: 18px;
        min-width: 18px;
    }

    .helper-text {
        margin-left: 30px;
    }
}

/* Forced colors mode for accessibility */
@media (forced-colors: active) {
    .checkbox-custom {
        border: 2px solid CanvasText;
        background: Canvas;
    }

    .checkbox-label input[type="checkbox"]:checked + .checkbox-custom {
        background: Highlight;
        border-color: HighlightText;
    }

    .submit-button {
        background: ButtonFace;
        color: ButtonText;
        border: 1px solid ButtonBorder;
    }

    .submit-button:focus {
        outline: 2px solid Highlight;
    }
}
